  "about_items": [
    {
      "n": "#273·12",
      "text": "This navy two-piece set is your anchor. The blazer features structured shoulders that draw the eye upward, while the tapered trousers offer a clean, elongated line to your legs. It cuts perfectly at your waist, creating a sharp, flattering silhouette."
    },
    {
      "n": "#499·01",
      "text": "The camel-colored coat is a long, belted piece with a high, structured collar. Its rich, warm tone provides a beautiful contrast to the navy beneath it, softening the overall look while maintaining an air of sophistication."
    },
    {
      "n": "#359·07",
      "text": "This black leather bag is small and rectangular with a simple strap closure. Its sleek design balances the formality of the suit without drawing unnecessary attention."
    },
    {
      "n": "#201·32",
      "text": "These black leather pumps are classic and polished, featuring a rounded toe and a slender heel that elevates your posture subtly."
    }
  ]
}
